<!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ramani Majengo | AI Architectural Planner</title>
<style>
:root{--bg:#07101b;--panel:#101d2d;--line:#29435f;--text:#f2f6fb;--muted:#a8b8ca;--accent:#38d0b7;--gold:#f2bd55}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#050c15,#0a1726 55%,#07111d);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.wrap{max-width:1450px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:10px 0 25px}.brand{font-size:25px;font-weight:900}.brand span{color:var(--accent)}.badge{border:1px solid var(--line);border-radius:999px;padding:8px 13px;color:var(--muted);font-size:13px}.hero{display:grid;grid-template-columns:1.1fr .9fr;gap:20px}.card,.panel{background:rgba(16,29,45,.96);border:1px solid var(--line);border-radius:20px;box-shadow:0 18px 50px rgba(0,0,0,.25)}.heroText{padding:36px}.hero h1{font-size:clamp(34px,5vw,64px);line-height:1.02;margin:0 0 16px}.hero h1 span{color:var(--accent)}.hero p{color:var(--muted);font-size:17px;line-height:1.7}.heroVisual{min-height:340px;overflow:hidden;position:relative;background:linear-gradient(135deg,#172b40,#0b1828)}.villa{position:absolute;inset:45px 35px 30px}.mass{position:absolute;left:10%;right:14%;bottom:30px;height:145px;background:linear-gradient(110deg,#e1d4bd,#bcae95);border:2px solid #7d7b75}.wing{position:absolute;right:4%;bottom:30px;width:28%;height:110px;background:#c9bba4;border:2px solid #77756f}.roof{position:absolute;left:5%;right:10%;top:40px;height:100px;background:#263b51;clip-path:polygon(8% 0,100% 35%,90% 100%,0 62%);border:2px solid #587087}.glass{position:absolute;bottom:65px;left:22%;width:25%;height:75px;background:#173b50;border:7px solid #303b45}.door{position:absolute;bottom:30px;left:54%;width:55px;height:110px;background:#5b402c;border:5px solid #3b3028}.light{position:absolute;bottom:53px;width:11px;height:11px;border-radius:50%;background:#f8d27b;box-shadow:0 0 25px #f8d27b}.l1{left:13%}.l2{left:80%}.panel{margin-top:22px;padding:24px}.panel h2{margin:0 0 5px}.sub{color:var(--muted);font-size:14px;line-height:1.5}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:18px}.field{display:flex;flex-direction:column;gap:7px}.full{grid-column:1/-1}label{font-size:13px;font-weight:800;color:#c9d6e3}input,select,textarea{width:100%;background:#091522;color:var(--text);border:1px solid #2b425c;border-radius:11px;padding:12px 13px;outline:none}textarea{min-height:190px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:var(--accent)}.required{color:var(--gold)}.briefHelp{padding:14px;border:1px solid #24425a;border-radius:12px;background:#0b1928;color:#9fb4c7;line-height:1.6}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.primary{background:var(--accent);color:#03231d;border:0;border-radius:12px;padding:13px 18px;font-weight:900}.secondary{background:#0b1828;color:var(--text);border:1px solid var(--line);border-radius:12px;padding:13px 18px}.status{display:none;margin-top:14px;padding:13px;border:1px solid var(--line);border-radius:10px;background:#091624;color:#c8d6e4;line-height:1.6}.status.show{display:block}.questions{margin:10px 0 0;padding-left:20px}.results{display:grid;grid-template-columns:1.35fr .65fr;gap:18px;margin-top:22px}.canvas{background:#edf1f4;border-radius:14px;padding:12px;overflow:auto;min-height:360px}.canvas svg{display:block;background:#fff;min-width:760px;width:100%;height:auto}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.tab{background:#0a1725;color:#cbd9e6;border:1px solid var(--line);border-radius:10px;padding:9px 12px}.tab.active{border-color:var(--accent);color:var(--accent)}.info{background:#0a1725;border:1px solid var(--line);border-radius:13px;padding:15px;margin-bottom:12px}.info strong{display:block;margin-bottom:7px}.info p{color:var(--muted);line-height:1.6;margin:0;white-space:pre-wrap}.notice{border-left:4px solid var(--gold);background:#211c10;color:#e8ddbe;padding:13px;border-radius:9px;margin-top:18px;line-height:1.55}.print{float:right}.footer{text-align:center;color:#8296aa;font-size:13px;padding:28px 0}@media(max-width:950px){.hero,.results{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.full{grid-column:auto}}@media print{body{background:white;color:#000}.top,.hero,.form,.tabs,.print,.footer,.notice{display:none!important}.wrap,.panel{padding:0;margin:0;border:0;box-shadow:none;background:#fff}.results{display:block}.canvas{padding:0}.canvas svg{min-width:0}}
</style></head><body><div class="wrap">
<header class="top"><div class="brand">RAMANI<span> MAJENGO</span></div><div class="badge">AI Architectural Concept Planner • Tanzania</div></header>
<section class="hero"><div class="card heroText"><h1>Eleza nyumba unayotaka. <span>AI ipange.</span></h1><p>Huhitaji kuandika majina ya vyumba moja moja. Eleza nyumba nzima kwa maneno yako mwenyewe — AI itachambua mahitaji, itambue spaces zinazohitajika, ipange circulation na ipendekeze vipimo vinavyolingana na kiwanja.</p><div class="notice">Hii ni architectural concept ya awali. Drawing ya mwisho ya ujenzi, structural calculations, approvals na compliance vinahitaji mtaalamu mwenye sifa.</div></div><div class="card heroVisual"><div class="villa"><div class="roof"></div><div class="mass"></div><div class="wing"></div><div class="glass"></div><div class="door"></div><div class="light l1"></div><div class="light l2"></div></div></div></section>
<section class="panel form" id="planner"><h2>1. Mahitaji ya mteja na kiwanja</h2><div class="sub">Upana na urefu wa kiwanja ni muhimu. Vipimo vya rooms si lazima — AI itavichambua kutoka kwenye maelezo yako.</div><div class="grid">
<div class="field"><label>Jina la project</label><input id="project" placeholder="Mfano: Nyumba ya Familia"></div><div class="field"><label>Jina la mteja</label><input id="client" placeholder="Mfano: Raymond"></div><div class="field"><label>Simu / contact (optional)</label><input id="contact" placeholder="Optional"></div><div class="field"><label>Eneo la ujenzi</label><input id="location" placeholder="Mfano: Dodoma, Tanzania"></div><div class="field"><label>Upana wa kiwanja (m) <span class="required">*</span></label><input id="plotW" type="number" min="1" step="0.1" placeholder="Mfano: 20"></div><div class="field"><label>Urefu wa kiwanja (m) <span class="required">*</span></label><input id="plotD" type="number" min="1" step="0.1" placeholder="Mfano: 30"></div><div class="field"><label>Upande wa barabara</label><select id="road"><option>North</option><option>East</option><option>South</option><option>West</option></select></div><div class="field"><label>Architectural style / preference (optional)</label><input id="style" placeholder="Mfano: modern tropical luxury, stone + wood"></div>
<div class="field full"><label>Maelezo ya mteja <span class="required">*</span></label><textarea id="brief" placeholder="Eleza nyumba unayotaka kwa uhuru. Mfano: Nataka nyumba ya familia ya kisasa kwenye kiwanja hiki. Iwe na master bedroom yenye privacy, bedrooms kwa watoto, living room kubwa inayofunguka kwenda garden, dining karibu na kitchen, pantry, veranda kubwa, parking ya magari mawili, natural light nyingi na facade yenye character. Sitaki nyumba ionekane kama box; nataka roof nzuri, materials za stone na wood na entrance ya kuvutia."></textarea><div class="briefHelp"><strong>Hapa ndipo maelezo yako yote yanapoanzia.</strong><br>Usiandike “Master Bedroom × 4 × 4” isipokuwa unataka kulazimisha kipimo fulani. Andika mahitaji, matumizi, watu watakaotumia nyumba, privacy, parking, outdoor spaces, style, floors na mambo mengine unayotaka. AI ndiyo itatoa spaces na vipimo vya concept.</div></div></div>
<div class="actions"><button class="primary" type="button" onclick="generatePlan()">✨ Tengeneza Architectural Concept</button><button class="secondary" type="button" onclick="resetForm()">Anza project mpya</button></div><div id="status" class="status"></div></section>
<section class="results"><div class="panel"><button class="secondary print" onclick="window.print()">🖨️ Print / PDF</button><h2>2. Design output</h2><div class="sub">Floor plan, dimensions, room flow na exterior concept hutokana na brief ya mteja.</div><div class="tabs"><button class="tab active" onclick="showView('floor',this)">Floor Plan</button><button class="tab" onclick="showView('dimensions',this)">Dimensions</button><button class="tab" onclick="showView('inside',this)">Room Flow</button><button class="tab" onclick="showView('outside',this)">Exterior Concept</button></div><div class="canvas" id="drawing"><div style="padding:70px;text-align:center;color:#66798e">Weka vipimo vya kiwanja na eleza nyumba unayotaka. AI itatengeneza concept.</div></div></div><div><div class="info"><strong>👤 Client brief</strong><p id="summary">Bado hakuna project.</p></div><div class="info"><strong>📐 Measurements</strong><p id="measurements">Bado hakuna vipimo.</p></div><div class="info"><strong>🚶 Room-to-room flow</strong><p id="experience">Bado hakuna circulation description.</p></div><div class="info"><strong>🏠 Exterior direction</strong><p id="preview">Bado hakuna exterior concept.</p></div></div></section><div class="footer">Ramani Majengo — AI-assisted architectural concept planning © 2026</div></div>
<script>
let plan=null;const $=id=>document.getElementById(id);function esc(s){return String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]));}
function payload(){return {project:$('project').value.trim(),client:$('client').value.trim(),contact:$('contact').value.trim(),location:$('location').value.trim(),plot_width:$('plotW').value,plot_depth:$('plotD').value,road_side:$('road').value,style:$('style').value.trim(),brief:$('brief').value.trim()};}
function setStatus(t,questions=[]){const s=$('status');s.innerHTML=esc(t)+(questions.length?'<ul class="questions">'+questions.map(q=>'<li>'+esc(q)+'</li>').join('')+'</ul>':'');s.className='status show';}
async function generatePlan(){const p=payload();if(!p.plot_width||!p.plot_depth){setStatus('❌ Weka upana na urefu wa kiwanja kwanza.');return}if(+p.plot_width<=0||+p.plot_depth<=0){setStatus('❌ Vipimo vya kiwanja lazima viwe zaidi ya sifuri.');return}if(!p.brief){setStatus('❌ Eleza nyumba unayotaka kwenye sehemu ya maelezo ya mteja.');return}setStatus('⏳ AI inasoma brief yako, inatambua spaces, inapangilia circulation na kuhesabu vipimo...');try{const r=await fetch('api/generate.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});const data=await r.json();if(!data.ok)throw new Error(data.message||'Imeshindikana');if(data.plan?.needs_clarification){setStatus('ℹ️ AI inahitaji maelezo machache zaidi kabla ya kuchora concept:',data.plan.questions||[]);return}plan=data.plan;$('summary').textContent=plan.summary||'';$('measurements').textContent=plan.measurements||'';$('experience').textContent=plan.room_experience||'';$('preview').textContent=plan.outside_preview||'';showView('floor',document.querySelector('.tab.active'));setStatus('✅ AI architectural concept imetengenezwa kutoka kwenye maelezo yako.');document.querySelector('.results').scrollIntoView({behavior:'smooth'})}catch(e){setStatus('❌ '+e.message)}}
function resetForm(){document.querySelectorAll('input,textarea').forEach(x=>x.value='');$('road').value='North';plan=null;$('status').className='status';$('drawing').innerHTML='<div style="padding:70px;text-align:center;color:#66798e">Weka vipimo vya kiwanja na eleza nyumba unayotaka. AI itatengeneza concept.</div>';$('summary').textContent='Bado hakuna project.';$('measurements').textContent='Bado hakuna vipimo.';$('experience').textContent='Bado hakuna circulation description.';$('preview').textContent='Bado hakuna exterior concept.';}
function showView(view,btn){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));if(btn)btn.classList.add('active');if(!plan)return;const el=$('drawing');if(view==='floor'||view==='dimensions')el.innerHTML=drawFloor(view==='dimensions');else if(view==='inside')el.innerHTML=drawFlow();else el.innerHTML=drawExterior();}
function drawFloor(dims){const rooms=plan.rooms||[],W=+plan.house_width||12,H=+plan.house_depth||10,s=65,p=70,cols=Math.max(1,Math.ceil(Math.sqrt(rooms.length))),rows=Math.ceil(rooms.length/cols),cw=W/cols,ch=H/rows,vw=W*s+p*2,vh=H*s+p*2;let cells=rooms.map((r,i)=>{let col=i%cols,row=Math.floor(i/cols),x=p+col*cw*s,y=p+row*ch*s;return `<g><rect x="${x}" y="${y}" width="${cw*s}" height="${ch*s}" fill="#fff" stroke="#263746" stroke-width="2"/><text x="${x+cw*s/2}" y="${y+ch*s/2-5}" text-anchor="middle" font-size="14" font-weight="700" fill="#152532">${esc(r.name)}</text><text x="${x+cw*s/2}" y="${y+ch*s/2+16}" text-anchor="middle" font-size="11" fill="#405565">${(+r.width).toFixed(1)} × ${(+r.depth).toFixed(1)} m</text></g>`}).join('');return `<svg viewBox="0 0 ${vw} ${vh}" xmlns="http://www.w3.org/2000/svg"><text x="${p}" y="28" font-size="18" font-weight="800">${esc(plan.title||'HOUSE PLAN')}</text><text x="${p}" y="49" font-size="12" fill="#536675">Footprint ${W.toFixed(1)}m × ${H.toFixed(1)}m${dims?' • dimension view':''}</text>${cells}<line x1="${p}" y1="${p+H*s+25}" x2="${p+W*s}" y2="${p+H*s+25}" stroke="#222"/><text x="${p+W*s/2}" y="${p+H*s+45}" text-anchor="middle" font-size="13">${W.toFixed(1)} m</text></svg>`;}
function drawFlow(){const rooms=plan.rooms||[];return `<div style="padding:25px;color:#172532;background:white;min-width:760px"><h3>Room-to-room movement</h3><p>Entrance → ${rooms.map(r=>esc(r.name)).join(' → ')}</p><p style="color:#5d6e7b;line-height:1.6">${esc(plan.room_experience||'AI-generated circulation description.')}</p></div>`;}
function drawExterior(){return `<div style="padding:30px;background:linear-gradient(135deg,#dfe9ef,#f8f5ef);min-width:760px;min-height:430px;color:#172532"><h3 style="margin-top:0">Exterior architectural concept</h3><div style="height:260px;position:relative;background:linear-gradient(#a9c8db 0 58%,#81936e 58%);overflow:hidden"><div style="position:absolute;left:12%;right:16%;bottom:45px;height:145px;background:#ded2bd;border:4px solid #5b5c5d;transform:skewY(-2deg)"></div><div style="position:absolute;left:27%;bottom:45px;width:24%;height:92px;background:#25475b;border:8px solid #3c4348"></div><div style="position:absolute;left:55%;bottom:45px;width:10%;height:125px;background:#62442d;border:5px solid #3c3028"></div><div style="position:absolute;left:73%;bottom:38px;width:16%;height:16px;background:#5f6668;border-radius:50%"></div></div><p style="line-height:1.6">${esc(plan.outside_preview||'Exterior concept based on the client brief.')}</p></div>`;}
</script></body></html>